import com.badlogic.gdx.ApplicationListener;
import com.badlogic.gdx.Gdx;
import com.badlogic.gdx.backends.headless.HeadlessApplication;
import com.badlogic.gdx.backends.headless.HeadlessApplicationConfiguration;

public class Main {
    public static void main(String[] args) throws Exception {
        String inputPath = null;
        for (String arg : args) {
            if (arg.startsWith("--input=")) {
                inputPath = arg.substring("--input=".length());
            }
        }
        if (inputPath == null) {
            System.err.println("Usage: gdx-game --input=<path>");
            System.exit(2);
        }

        ScriptedInput scriptedInput;
        try {
            scriptedInput = new ScriptedInput(inputPath);
        } catch (IllegalArgumentException e) {
            System.err.println("Error: " + e.getMessage());
            System.exit(1);
            return;
        }

        HeadlessApplicationConfiguration config = new HeadlessApplicationConfiguration();
        config.updatesPerSecond = 60;
        // Render at every update
        config.renderInterval = 1.0f / 60.0f;

        WalkerGame game = new WalkerGame();
        HeadlessApplication app = new HeadlessApplication(game, config);
        // Overwrite Gdx.input with our scripted version
        Gdx.input = scriptedInput;
        // Re-register input processor now that we replaced Gdx.input
        Gdx.input.setInputProcessor(game);

        // Drive the simulation in a separate thread: dispatch one key per tick then call Gdx.app.exit() when exhausted
        Thread driver = new Thread(() -> {
            try {
                while (!scriptedInput.isExhausted()) {
                    Thread.sleep(1000L / 60L);
                    // Dispatch on the application thread via postRunnable
                    final boolean[] done = {false};
                    Gdx.app.postRunnable(() -> {
                        scriptedInput.dispatchNext();
                        done[0] = true;
                    });
                    // Wait briefly so we don't busy loop
                    long start = System.currentTimeMillis();
                    while (!done[0] && (System.currentTimeMillis() - start) < 1000) {
                        Thread.sleep(1);
                    }
                }
                Gdx.app.postRunnable(() -> Gdx.app.exit());
            } catch (InterruptedException e) {
                Thread.currentThread().interrupt();
            }
        });
        driver.setDaemon(true);
        driver.start();

        // Block main thread on the application to keep JVM alive
        app.getApplicationListener().create(); // already called by HeadlessApplication; harmless
        // The HeadlessApplication runs its own main loop on a non-daemon thread; join it.
        // We can do this by waiting for Gdx.app to be exiting. Simpler approach: just spin.
        while (Gdx.app != null) {
            Thread.sleep(50);
            // Check if app exited - HeadlessApplication sets thread interrupted/exited. We don't have direct API
            // so use a sentinel: after exit, the headless thread ends. We'll join the runtime's main thread.
            // Best approach: use a timeout-based polling and check whether the runtime thread is alive.
            // Simpler: just join via reflection or rely on the shutdown hook. For now, sleep then exit when done.
            if (Thread.currentThread().isInterrupted()) break;
            // Check if we should stop: we use a small heuristic - exit when we're sure app is done
            // Use System.gc-free polling with a sleep cap.
        }
        System.out.println("Final position: (" + game.getX() + ", " + game.getY() + ")");
        System.exit(0);
    }
}
